var articles = $input.all().filter(function(item) { return item.json.id; });
if (articles.length === 0) {
  throw new Error('No approved articles found. Brett needs to approve articles in Telegram first.');
}
return articles;

var articles = $('Check Articles').all();
var count = articles.length;

var template = 'standard_daily';
var templateLabel = 'Standard Daily (5 min)';
if (count === 1) {
  template = 'deep_dive';
  templateLabel = 'Deep Dive (10 min)';
} else if (count >= 5) {
  template = 'weekly_roundup';
  templateLabel = 'Weekly Roundup (15 min)';
}

var selected;
if (template === 'standard_daily') {
  selected = articles.slice(0, 4);
} else if (template === 'deep_dive') {
  selected = articles.slice(0, 1);
} else {
  selected = articles.slice(0, 7);
}

var combined = selected.map(function(item, i) {
  var content = item.json.content || item.json.title || '';
  return 'Article ' + (i + 1) + ': ' + (item.json.title || 'Untitled') +
    '\nURL: ' + (item.json.url || '') +
    '\nCategory: ' + (item.json.score_category || item.json.category || 'general') +
    '\nScore: ' + (item.json.composite_score || 'N/A') + '/10' +
    '\nContent: ' + content.substring(0, 2000);
}).join('\n\n---\n\n');

var articleUrls = selected.map(function(a) { return a.json.url; });
var articleTitles = selected.map(function(a) { return a.json.title; });

return [{
  json: {
    allArticles: combined,
    articleCount: selected.length,
    template: template,
    templateLabel: templateLabel,
    articleUrls: articleUrls,
    articleTitles: articleTitles
  }
}];

var articleUrls = $('Select Template').item.json.articleUrls;
return articleUrls.map(function(url) {
  return { json: { url: url } };
});

