={{ (function() {
var tmpl = $('Select Template').item.json.templateLabel;
var count = $('Select Template').item.json.articleCount;
var titles = $('Select Template').item.json.articleTitles;
var script = $('Generate Script').item.json.text;
var words = script.split(' ').length;
var msg = 'Episode Script Generated\n\n';
msg += 'Template: ' + tmpl + '\n';
msg += 'Articles: ' + count + '\n';
for (var i = 0; i < titles.length; i++) {
  msg += '  ' + (i + 1) + '. ' + titles[i] + '\n';
}
msg += '\nWord count: ' + words + '\n';
msg += '\nFull script saved to database. View in dashboard.';
return msg;
})() }}
